import type { PromptToken } from './prompt-token-library';

type DirectRow = readonly [id: string, label: string, illustrious: string, sdxl?: string, natural?: string];

const direct = (category: string, group: string, rows: readonly DirectRow[]): PromptToken[] => rows.map(([id, label, illustrious, sdxl, natural]) => {
  const sdxlValue = sdxl || illustrious;
  return { id, scope: 'positive', category, group, label, values: { illustrious, sdxl: sdxlValue, natural: natural || sdxlValue } };
});

